#!/bin/bash
# One-off local install for THIS tablet. Not a package -- packaging comes later,
# once the driver has been reviewed by someone other than us.
#
# What it does, and why each step:
#   * masks stock fprintd  -- both services want the same bus name, and fprintd
#                             has no device here anyway ("No devices available")
#   * installs the unit    -- bring-up runs at start and the session is held, so
#                             Claim fits inside pam_fprintd's timeout=10
#   * does NOT touch PAM   -- /etc/pam.d/common-auth is generated by
#                             pam-auth-update; edits there do not survive
#
# Read packaging/README.md first. This puts unreviewed code in your login path.
set -euo pipefail
[[ $EUID -eq 0 ]] || { echo "run me with sudo"; exit 1; }
HERE="$(cd "$(dirname "$0")" && pwd)"

echo "== masking stock fprintd"
systemctl stop fprintd.service 2>/dev/null || true
systemctl mask fprintd.service

echo "== installing the runtime"
# SYNASPI_PV_DIR / SYNASPI_RECOVERED are passed straight through -- see
# install-runtime.sh for what they must point at.
"$HERE/install-runtime.sh"

echo "== installing the unit"
install -m 0644 "$HERE/synaspi-fprintd.service" /etc/systemd/system/
systemctl daemon-reload

# Repoint D-Bus activation at our unit. Without this the greeter's early
# GetDevices (it runs ~12 s before our bring-up finishes) fails with
# "fprintd.service is masked" and the login screen offers no fingerprint until
# you re-select your user. /usr/local/share wins over the fprintd package's
# copy in /usr/share and survives its upgrades.
echo "== repointing D-Bus activation"
install -d /usr/local/share/dbus-1/system-services
install -m 0644 "$HERE/net.reactivated.Fprint.activation.service" \
    /usr/local/share/dbus-1/system-services/net.reactivated.Fprint.service
systemctl reload dbus || true
# enable, not just start: without this it is gone after a reboot
systemctl enable --now synaspi-fprintd.service

echo "== waiting for bring-up (~11 s)"
for _ in $(seq 1 30); do
    if gdbus call --system --dest net.reactivated.Fprint \
        --object-path /net/reactivated/Fprint/Manager \
        --method net.reactivated.Fprint.Manager.GetDefaultDevice >/dev/null 2>&1
    then echo "   service is on the bus"; break; fi
    sleep 1
done

U="${SUDO_USER:-$USER}"
cat <<MSG

test it:
    fprintd-list $U      # should list the enrolled finger
    fprintd-verify $U    # press when it asks
    sudo -k && sudo true           # the real thing: PAM

roll back (either of these is enough):
    sudo systemctl stop synaspi-fprintd && sudo systemctl unmask --now fprintd
    sudo ./packaging/uninstall-local.sh
MSG
